INSERT INTO `companies` (`id`, `assets`, `name`, `slug`, `email`, `phone`, `document`, `description`, `status`, `deleted_at`, `created_at`, `updated_at`, `company_id`, `user_id`) VALUES
('3c4624d9-42e1-4ddb-b39c-5f6d95e8c93f', 'estatuasoliveira.com.br', 'Estatuas Oliveira', 'siga-smart-sistemas', 'contato@estatuasoliveira.com.br', '+55 51 999732078', '10.272.845-0001-90', 'Há mais de 25 anos no mercado nossa empresa "Estátuas Oliveira " se dedica a proporcionar o embelezamento de ambientes. Fabricamos vários itens em cimento, mármore e gesso para decorar sua casa, sítio e jardim. Além de uma infinidade de estátuas, vasos, fontes, bancos, mesas e decorações temos também opções em cerâmica. Venham conhecer nossos produtos em meio de um lugar agradável ao ar livre com muitas árvores e aquários naturais. Aguardamos a sua visita.!\r\n\r\n..............................................................................................................................................................................................................................\r\n\r\nSobre Nós\r\nHá mais de 25 anos no mercado nossa empresa "Estátuas Oliveira" se dedica a proporcionar o embelezamento de ambientes. Fabricamos vários itens em cimento, mármore e gesso para decorar sua casa, sítio e jardim. Além de uma infinidade de estátuas, vasos, fontes, bancos, mesas e decorações temos também opções em cerâmica. Venham conhecer nossos produtos em meio de um lugar agradável ao ar livre com muitas árvores e aquários naturais. Aguardamos a sua visita.!', 'published', NULL, '2020-04-28 20:51:34', '2022-03-25 22:43:12', '3c4624d9-42e1-4ddb-b39c-5f6d95e8c93f', NULL);
